use super::*;
use crate::os_store::ArtifactCanonicalTreeSource;
use semio_framework_value::DslValue;
fn field<'a>(root:&'a DslValue,key:&str)->&'a DslValue{let DslValue::Object(fields)=root else{panic!("authored fixture object")};&fields.iter().find(|(name,_)|name==key).unwrap().1}
fn array(root:&DslValue)->&[DslValue]{let DslValue::Array(rows)=root else{panic!("authored fixture array")};rows}
fn text(root:&DslValue)->&str{let DslValue::String(value)=root else{panic!("authored fixture text")};value}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
#[test]
fn canonical_source_identity_streams_original_full_fields_and_closes_every_cancelled_prefix(){
 let law: DslValue=semio_framework_pack_json::from_json_str(include_str!("./🧫️fixtures/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();
 for case in array(field(&law,"cases")){let roots=array(field(case,"roots"));let addresses=roots.iter().map(|root|root as*const DslValue as usize).collect::<Vec<_>>();let stops=[None,Some(0),Some(1),Some(17),Some(53),Some(113)];
 for stop in stops{let d=ArtifactCanonicalSourceIdentityCursor::constructor_demand();let((mut cursor,birth),heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||ArtifactCanonicalSourceIdentityCursor::admit(roots.len(),grant(d)).unwrap().unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(birth.fits(grant(d)));let mut transcript=Vec::with_capacity(text(field(case,"transcriptHex")).len()/2);let mut completed=false;
 for turn in 0..100000{if stop==Some(turn){break;}let d=cursor.next_demand();let denied=RetainedCloneGrant{maximum_copy_bytes:0,maximum_items:0,..grant(d)};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(None,denied).unwrap());assert_eq!(result.progress,Default::default());assert!(result.byte.is_none());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let source=cursor.source_index().map(|index|ArtifactCanonicalTreeSource::view(&roots[index])as &dyn ArtifactCanonicalJson);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source,grant(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(result.progress.retained_capacity_bytes,result.progress.released_bytes));assert!(result.progress.fits(grant(d)));assert_ne!(result.progress,Default::default());if let Some(byte)=result.byte{transcript.push(byte);}assert_eq!(roots.iter().map(|root|root as*const DslValue as usize).collect::<Vec<_>>(),addresses);if result.ready{completed=true;break;}}
 if completed{assert_eq!(semio_framework_hash::sha256_hex(&transcript),text(field(case,"sha256")));assert_eq!(*cursor.digest().unwrap(),semio_framework_hash::Sha256::digest(&transcript));}else{assert!(stop.is_some());}
 cursor.begin_close();let d=cursor.next_demand();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(RetainedCloneGrant{maximum_copy_bytes:0,..grant(d)}).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(!cursor.terminal_is_empty());let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.close_step(grant(d)).unwrap());assert!(result.progress.fits(grant(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(cursor.terminal_is_empty());assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor)).1.released_bytes,0);
 }}
}
#[test]
fn canonical_source_identity_refuses_a_foreign_live_root_before_reading_it(){
 let original=DslValue::Object(vec![("value".into(),DslValue::int(1))]);let foreign=DslValue::Object(vec![("value".into(),DslValue::int(1))]);let(mut cursor,_)=ArtifactCanonicalSourceIdentityCursor::admit(1,grant(ArtifactCanonicalSourceIdentityCursor::constructor_demand())).unwrap().unwrap();
 while cursor.source_index().is_none(){let d=cursor.next_demand();cursor.advance(None,grant(d)).unwrap();}
 let d=cursor.next_demand();cursor.advance(Some(ArtifactCanonicalTreeSource::view(&original)),grant(d)).unwrap();let d=cursor.next_demand();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(Some(ArtifactCanonicalTreeSource::view(&foreign)),grant(d)));assert!(result.is_err());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));cursor.begin_close();let d=cursor.next_demand();cursor.close_step(grant(d)).unwrap();assert!(cursor.terminal_is_empty());
}

/// 🧬️ Shared 64-slot birth retains its one exact allocation across denied initialization, deep roots and every cancellation prefix.
#[test]
fn canonical_source_identity_staged64_birth_deep_source_and_cancellation_fit4096(){
 assert!(!std::mem::needs_drop::<super::super::JsonFrame>());let mut root=DslValue::String("deep original".into());for _ in 0..63{root=DslValue::Array(vec![root]);}let original=&root as*const DslValue as usize;
 for stop in[None,Some(0),Some(1),Some(2),Some(17),Some(64),Some(65),Some(66),Some(67),Some(68)]{let mut birth=ArtifactCanonicalSourceIdentityBirth::default();let mut born=0;let mut released=0;let mut delivered=None;let mut address=None;
 for turn in 0..70{if stop==Some(turn){break;}let d=birth.next_demand();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);let before=(birth.original_backing_identity(),birth.initialized_slots());for axis in 0..3{let mut denied=grant(d);match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes=d.copy_bytes-1,2 if d.capacity_bytes!=0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,_=>continue};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||birth.advance(1,denied).unwrap());assert!(result.0.is_none());assert_eq!(result.1,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((birth.original_backing_identity(),birth.initialized_slots()),before);}
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||birth.advance(1,grant(d)).unwrap());assert!(result.1.fits(grant(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(result.1.retained_capacity_bytes,result.1.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;if address.is_none(){address=birth.original_backing_identity();}if let Some(cursor)=result.0{assert_eq!(Some(&*cursor as*const ArtifactCanonicalSourceIdentityCursor as usize),address);delivered=Some(cursor);break;}assert_eq!(birth.original_backing_identity(),address);}
 if stop.is_none(){let mut oracle=serde_json::Value::String("deep original".into());for _ in 0..63{oracle=serde_json::Value::Array(vec![oracle]);}let mut expected=b"semio.canonical-source-identity/v1".to_vec();expected.push(0);expected.extend_from_slice(&1u64.to_be_bytes());serde_json::to_writer(&mut expected,&[oracle]).unwrap();let mut actual=Vec::with_capacity(expected.len());let cursor=delivered.as_mut().unwrap();for _ in 0..100000{let d=cursor.next_demand();assert!(d.copy_bytes<=4096);let source=cursor.source_index().map(|_|ArtifactCanonicalTreeSource::view(&root)as&dyn ArtifactCanonicalJson);let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source,grant(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(step.progress.fits(grant(d)));if let Some(byte)=step.byte{actual.push(byte);}if step.ready{break;}}assert!(cursor.is_ready());assert_eq!(actual,expected,"deep original source transcript matches independent Serde JSON");assert_eq!(&root as*const DslValue as usize,original);cursor.begin_close();let d=cursor.next_demand();assert!(d.copy_bytes<=4096);cursor.close_step(grant(d)).unwrap();let frame=delivered.take().unwrap();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(frame));released+=heap.released_bytes;assert_eq!(heap.released_bytes,size_of::<ArtifactCanonicalSourceIdentityCursor>());}else{assert!(delivered.is_none());}
 while !birth.terminal_is_empty(){let d=birth.close_demand();assert!(d.copy_bytes<=4096&&d.release_bytes<=4096);let before=(birth.original_backing_identity(),birth.initialized_slots());let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||birth.close_step(RetainedCloneGrant{maximum_items:0,..grant(d)}).unwrap());assert_eq!(p,Default::default());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!((birth.original_backing_identity(),birth.initialized_slots()),before);let(p,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||birth.close_step(grant(d)).unwrap());assert!(p.fits(grant(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;}
 assert_eq!(born,released);assert_eq!(semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(birth)).1.released_bytes,0);}
}
/// 🚧️ The original65-level tree receives an explicit source-depth refusal before any out-of-bounds frame access.
#[test]
fn canonical_source_identity_staged64_refuses_original_source_depth65_and_closes_paid_backing(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("./🧫️fixtures/🔣️.json")).unwrap();let maximum=fixture["maximumSourceDepth"].as_u64().unwrap();let mut root=DslValue::String("deep original".into());for _ in 0..maximum{root=DslValue::Array(vec![root]);}let mut birth=ArtifactCanonicalSourceIdentityBirth::default();let mut cursor=None;let mut born=0;let mut released=0;
 for _ in 0..70{let d=birth.next_demand();assert!(d.copy_bytes<=4096&&d.capacity_bytes<=4096);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||birth.advance(1,grant(d)).unwrap());assert_eq!((heap.requested_bytes,heap.released_bytes),(result.1.retained_capacity_bytes,result.1.released_bytes));born+=heap.requested_bytes;released+=heap.released_bytes;if result.0.is_some(){cursor=result.0;break;}}
 let mut cursor=cursor.unwrap();let mut refused=false;for _ in 0..100000{let d=cursor.next_demand();let source=cursor.source_index().map(|_|ArtifactCanonicalTreeSource::view(&root)as&dyn ArtifactCanonicalJson);let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(source,grant(d)));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));match result{Ok(step)=>{assert!(step.progress.fits(grant(d)));assert!(!step.ready);},Err(error)=>{assert_eq!(error.kind,ValueRefusalKind::DepthLimit);assert!(error.retained_progress().fits(grant(d)));assert!(error.retained_progress().copied_items>0&&error.retained_progress().copied_bytes>=META);refused=true;break;}}}
 assert!(refused);cursor.begin_close();let d=cursor.next_demand();assert!(d.copy_bytes<=4096);cursor.close_step(grant(d)).unwrap();let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(cursor));released+=heap.released_bytes;assert_eq!(born,released);assert!(birth.terminal_is_empty());
}